274	  runModelLoad(path: string): Promise<THREE.Object3D> {
275	    return this._loadModel(path);
276	  }
277	
278	  async setObject(id: string, object: SceneObject): Promise<void> {
279	    await this._scene.addObject(id, object);
280	  }
281	
282	  getScene(): Scene {
283	    return this._scene;
284	  }
285	
286	  setState(state: SceneFromState): void {
287	    const cam = state.camera;
288	    if (cam) {
289	      this._applyCamState(cam);
290	    }
291	    const camTarget = state.cameraTarget;
292	    if (camTarget?.position) {
293	      this.setCameraTargetPosition(
294	        this._num(camTarget.position.x),
295	        this._num(camTarget.position.y),
296	        this._num(camTarget.position.z),
297	      );
298	    }
299	    const scene = this._scene;
300	    for (const [targetId, vars] of Object.entries(state)) {
301	      if (
302	        targetId === cameraId ||
303	        targetId === cameraTargetId ||
304	        vars == null ||
305	        typeof vars !== "object"
306	      )
307	        continue;
308	      const obj = scene.getObject(targetId);
309	      if (!obj) continue;
310	      if (hasPositionSet(obj)) {
311	        this._applyVector3(obj, vars as ObjectVars);
312	        this._applyScalarProps(
313	          obj as unknown as Record<string, unknown>,
314	          vars as Record<string, unknown>,
315	        );
316	        continue;
317	      }
318	      if (!this._isPlainRecord(obj)) continue;
319	      this._applyScalarProps(obj, vars as Record<string, unknown>);
320	    }
321	  }
322	
323	  private _applyCamState(cam: CameraVars): void {
324	    this._applyVector3(this._camera, cam, false);
325	    if (cam.fov == null || !Number.isFinite(cam.fov)) return;
326	    this._camera.fov = cam.fov;
327	    this._camera.updateProjectionMatrix();
328	  }
329	
330	  private _num(v: number | undefined): number {
331	    return v != null && Number.isFinite(v) ? v : 0;
332	  }
333	
334	  private _applyVector3(
335	    obj: HasPositionSet,
336	    vars: ObjectVars | CameraVars,
337	    applyRotation = true,
338	  ): void {
339	    if (vars.position)
340	      obj.position.set(
341	        this._num(vars.position.x),
342	        this._num(vars.position.y),
343	        this._num(vars.position.z),
344	      );
345	    if (applyRotation && "rotation" in vars && vars.rotation && obj.rotation) {
346	      const r = Helpers.rotationDegToRad({
347	        x: this._num(vars.rotation.x),
348	        y: this._num(vars.rotation.y),
349	        z: this._num(vars.rotation.z),
350	      });
351	      obj.rotation.set(r.x, r.y, r.z);
352	    }
353	    if (vars.scale && obj.scale)
354	      obj.scale.set(
355	        this._num(vars.scale.x),
356	        this._num(vars.scale.y),
357	        this._num(vars.scale.z),
358	      );
359	  }
360	
361	  private _isPlainRecord(obj: unknown): obj is Record<string, unknown> {
362	    if (
363	      obj == null ||
364	      typeof obj !== "object" ||
365	      Array.isArray(obj) ||
366	      obj instanceof THREE.Object3D
367	    ) {
368	      return false;
369	    }
370	    const proto = Object.getPrototypeOf(obj);
371	    return proto === Object.prototype || proto === null;
372	  }
373	
374	  private _applyScalarProps(
375	    target: Record<string, unknown>,
376	    vars: Record<string, unknown>,
377	  ): void {
378	    for (const [key, value] of Object.entries(vars)) {
379	      if (key === "position" || key === "rotation" || key === "scale") continue;
380	      if (typeof value === "number" && Number.isFinite(value)) {
381	        target[key] = value;
382	        continue;
383	      }
384	      if (typeof value === "boolean" || typeof value === "string") {
385	        target[key] = value;
386	        continue;
387	      }
388	      if (this._isPlainRecord(value)) {
389	        const current = target[key];
390	        const nextTarget = this._isPlainRecord(current) ? current : {};
391	        target[key] = nextTarget;
392	        this._applyScalarProps(nextTarget, value);
393	      }
394	    }
395	  }
