421	  setCameraTargetPosition(x: number, y: number, z: number): void {
422	    this._cameraTargetFollow = null;
423	    this._cameraTargetFollowAnchorNode = null;
424	    this._cameraTargetFollowLocalAnchor = null;
425	    this._cameraTarget.position.set(
426	      Number.isFinite(x) ? x : this._cameraTarget.position.x,
427	      Number.isFinite(y) ? y : this._cameraTarget.position.y,
428	      Number.isFinite(z) ? z : this._cameraTarget.position.z,
429	    );
